package pe.nexo.store.admin;import org.springframework.web.bind.annotation.*;import pe.nexo.store.order.*;import java.math.BigDecimal;import java.util.*;
@RestController@RequestMapping("/api/admin/customers")public class CustomerController{private final OrderService orders;public CustomerController(OrderService orders){this.orders=orders;}public record Customer(Long id,String name,String email,long orderCount,BigDecimal totalSpent,List<AdminOrderResponse>orders){}private List<Customer>customers(){Map<String,List<CustomerOrder>>groups=new LinkedHashMap<>();orders.findAll().forEach(o->groups.computeIfAbsent(o.getEmail(),x->new ArrayList<>()).add(o));return groups.values().stream().map(list->{CustomerOrder first=list.get(0);BigDecimal total=list.stream().filter(o->o.getStatus()!=OrderStatus.CANCELLED).map(CustomerOrder::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);return new Customer(first.getId(),first.getCustomerName(),first.getEmail(),list.size(),total,list.stream().map(AdminOrderResponse::from).toList());}).toList();}@GetMapping public List<Customer>all(){return customers().stream().map(c->new Customer(c.id(),c.name(),c.email(),c.orderCount(),c.totalSpent(),null)).toList();}@GetMapping("/{id}")public Customer one(@PathVariable Long id){return customers().stream().filter(c->c.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Cliente no encontrado"));}}
